import * as M from './model.js';
import * as A from './academic-year.js';
import * as P from './planner.js';
import * as Career from './career.js';
export const COURSES=[{id:'safety',name:'학교안전교육',hours:15,cycle:3,practice:0,question:'안전 점검 결과는 어떻게 이어 갈까요?',yes:'담당자와 개선 일정·재확인을 남긴다.',no:'점검표를 작성한 것으로 모두 해결됐다고 본다.'},{id:'firstaid',name:'응급처치 교육',hours:3,cycle:1,practice:2,question:'실습이 필요한 과정은 어떻게 이수할까요?',yes:'학교의 전문 강사와 집합 실습에 참여한다.',no:'온라인 자료 열람으로 실습까지 대체한다.'},{id:'violence',name:'학교폭력 예방교육',hours:1,cycle:.5,practice:0,question:'도움을 요청한 학생에게 먼저 할 일은?',yes:'안전을 확인하고 담당자에게 사실과 요청을 전달한다.',no:'친밀도가 낮으니 나중에 확인한다.'},{id:'teacher-rights',name:'교육활동 보호 예방교육',hours:1,cycle:1,practice:0,question:'혼자 해결하기 어려운 상황에서는?',yes:'학교의 대응 체계와 공식 지원을 요청한다.',no:'모든 연락을 담임 개인이 계속 맡는다.'},{id:'character',name:'인성교육',hours:1,cycle:1,practice:0,question:'서로 다른 의견을 다룰 때는?',yes:'이유를 듣고 참여할 수 있는 방법을 함께 정한다.',no:'조용한 학생의 의견은 확인하지 않는다.'},{id:'child-support',name:'아동 보호·신고의무자 교육',hours:1,cycle:1,practice:0,question:'지원이 필요한 정황을 알게 되면?',yes:'안전을 우선하고 학교 절차와 필요한 신고·지원 경로를 확인한다.',no:'문제가 확실히 해결될 때까지 기록하지 않는다.'},{id:'welfare',name:'긴급복지 신고의무 교육',hours:1,cycle:1,practice:0,question:'생활 지원 정보는 어떻게 공유할까요?',yes:'필요한 담당자에게 최소한의 확인 정보를 전달한다.',no:'반 전체 안내문에 가정 사정을 적는다.'},{id:'multicultural',name:'다문화 이해교육',hours:15,cycle:3,practice:0,question:'가족이 사용하는 언어가 다를 때는?',yes:'희망하는 소통 방법과 통번역 지원을 확인한다.',no:'가정 배경만으로 학업 수준을 판단한다.'},{id:'privacy',name:'개인정보·정보보안 교육',hours:1,cycle:1,practice:0,question:'학생 자료를 공유하기 전에는?',yes:'대상·목적·필요한 항목과 접근 범위를 확인한다.',no:'명렬표와 개인 메모를 모두 같은 파일로 보낸다.'},{id:'integrity',name:'청렴·이해충돌 사례 연수',hours:1,cycle:1,practice:0,question:'업무와 이해관계가 겹칠 가능성이 있다면?',yes:'학교에 알리고 적용 절차를 확인한다.',no:'개인적으로 판단하고 기록을 남기지 않는다.'},{id:'disability',name:'장애 인식개선 교육',hours:1,cycle:1,practice:0,question:'참여가 어려운 학생을 지원하려면?',yes:'학생의 의사와 필요한 접근 지원을 먼저 확인한다.',no:'진단 이름만으로 활동에서 제외한다.'}];
export function data(s){return s.staffWork??={schema:1,year:s.academic?.year||2030,training:[],business:[],social:[],projects:null,currentAudit:null,away:null,committees:[],organizations:[],history:[]};}
export function free(s,minutes,exclude=null){const slot=M.currentSlot(s);return !s.teacherDuty?.away&&!M.movementBusy(s)&&!data(s).away&&['morning','break','afternoon','specialist'].includes(slot.kind)&&s.minute+minutes<=Math.min(1000,slot.end)&&!P.conflicts(s,s.day,s.minute,s.minute+minutes,exclude).length;}
const periodKey=(s,c)=>c.cycle===.5?s.academic.year+'-'+A.term(s):c.cycle===3?Math.floor((s.academic.year-2030)/3):s.academic.year;
export function trainingStatus(s,id){const c=COURSES.find(x=>x.id===id);if(!c)return null;const rows=data(s).training.filter(r=>r.courseId===id&&r.period===periodKey(s,c)),theory=rows.filter(r=>!r.practice).reduce((n,r)=>n+r.hours,0),practice=rows.filter(r=>r.practice).reduce((n,r)=>n+r.hours,0);return {course:c,theory,practice,complete:theory>=c.hours-c.practice&&practice>=c.practice,remaining:Math.max(0,c.hours-theory-practice),validThrough:c.cycle===3?2032+Math.floor((s.academic.year-2030)/3)*3:s.academic.year};}
export function train(s,id,practice,choice){const t=trainingStatus(s,id);if(!t)return false;if(t.complete)return {error:'이번 유효 기간의 이수 조건을 충족했습니다.'};if(practice&&!t.course.practice)return {error:'이 과정은 별도 실습 시간이 없습니다.'};if(practice&&s.room!=='gym')return {error:'집합 실습은 강당·체육관의 전문 강사와 진행합니다.'};if(!practice&&!['classroom','staff','research'].includes(s.room))return {error:'교실·교무실·교사연구실에서 원격 과정을 수강해 주세요.'};if((practice?t.practice>=t.course.practice:t.theory>=t.course.hours-t.course.practice))return {error:practice?'실습 조건을 충족했습니다.':'이론 조건을 충족했습니다. 실습을 확인해 주세요.'};if(!free(s,60))return {error:'수업·약속과 겹치지 않는 60분이 필요합니다.'};M.advance(s,60);if(choice!==0)return {error:'사례를 다시 확인해 주세요. 학습 시간만 지나고 이수로 확정하지 않았습니다.'};data(s).training.push({courseId:id,period:periodKey(s,t.course),year:s.academic.year,term:A.term(s),hours:1,practice:!!practice,date:M.stamp(s),day:s.day});M.log(s,t.course.name+' '+(practice?'실습':'이론')+' 1시간 이수');return {ok:true};}
export function requestTrip(s,title,day,start,end){const d=data(s);if(!String(title).trim()||day>s.academic.end||!A.schoolDay(s,day)||day<s.day||start<900||end>1000||end-start<60||day===s.day&&start<s.minute||M.todaySchedule({...s,day}).some(r=>r.start<end&&r.end>start)||P.conflicts(s,day,start,end).length)return {error:'담임 수업·약속과 겹치지 않는 등교일의 수업 후 60분 이상을 선택해 주세요.'};const trip={id:'business-'+s.academic.year+'-'+d.business.length,title:String(title).slice(0,100),day,start,end,status:'requested',travelMinutes:20,report:'',handoff:false};d.business.push(trip);M.addMessage(s,'all','한정우 교감',`${trip.title} 출장 신청을 받았습니다. 남은 학생의 담당 인계와 복귀 시간을 확인해 주세요.`,{senderId:'principal',plannerScanned:true});return {ok:true};}
export function business(s,id,action,note=''){const d=data(s),t=d.business.find(x=>x.id===id);if(!t)return false;if(action==='approve'&&t.status==='requested'){t.status='approved';t.handoff=true;P.upsert(s,{...t,room:'district',type:'personal',response:'참석',status:'예정',source:'승인된 출장',businessId:t.id});return {ok:true};}if(action==='cancel'&&['requested','approved'].includes(t.status)){t.status='cancelled';const p=P.data(s).entries.find(e=>e.id===id);if(p)p.status='취소';return {ok:true};}if(action==='depart'&&t.status==='approved'){if(t.day!==s.day||s.minute>t.start||s.minute<880||!t.handoff||P.conflicts(s,s.day,t.start,t.end,id).length||M.currentSlot(s).kind!=='afternoon')return {error:'승인된 당일 수업 후, 출장 시작 전에 담당 인계를 확인해 주세요.'};M.advance(s,t.start+10-s.minute);d.away=id;t.status='on-site';s.room='district';return {ok:true};}if(action==='return'&&t.status==='on-site'){if(String(note).trim().length<8)return {error:'현장에서 확인한 내용과 학교에 공유할 점을 적어 주세요.'};M.advance(s,Math.max(0,t.end-s.minute));t.status='completed';t.report=String(note).slice(0,1000);t.completed=M.stamp(s);d.away=null;s.room='staff';const p=P.data(s).entries.find(e=>e.id===id);if(p)p.status='완료';M.addNote(s,'teacher',t.title+' 출장 결과: '+t.report);return {ok:true};}return {error:'출장 단계와 시간을 확인해 주세요.'};}
export function social(s,choice){const d=data(s),key=s.day;if(d.social.some(r=>r.day===key))return {error:'오늘 모임 응답을 이미 기록했습니다.'};if(!['join','decline','early'].includes(choice))return false;if(choice!=='decline'&&!free(s,choice==='early'?10:30))return {error:'수업 후 약속이 없는 시간을 확보해 주세요.'};if(M.currentSlot(s).kind!=='afternoon')return {error:'교직원 식사 모임은 수업 후에 선택해요.'};if(choice!=='decline')M.advance(s,choice==='early'?10:30);d.social.push({day:s.day,choice,date:M.stamp(s)});M.addMessage(s,'grade','윤서진',choice==='decline'?'알겠습니다. 편하게 쉬세요. 필요한 업무 내용은 학교톡으로 별도 공유할게요.':choice==='early'?'먼저 들어가셔도 괜찮아요. 잠깐 안부를 나누어서 반가웠어요.':'오늘은 식사하며 가벼운 안부를 나누어요. 학생의 개인 정보는 이야기하지 않기로 해요.',{senderId:'colleague',plannerScanned:true});return {ok:true};}
export function project(s){const d=data(s),school=Career.data(s).schools.find(x=>x.id===Career.data(s).schoolId);if(!d.projects)d.projects={topic:school.leading,year:s.academic.year,selected:s.academic.year<=school.projectEnd,goal:'',required:11,shared:false,renewed:false};const p=d.projects;return {...p,lessons:s.lessonResults.filter(r=>(r.tags||[]).includes(p.topic)).length};}
export function planProject(s,goal){const p=project(s);if(!p.selected)return {error:'현재 학교의 선도사업 지정 기간이 끝났습니다.'};if(String(goal).trim().length<8)return {error:'우리 반 수업과 연결할 목표를 적어 주세요.'};data(s).projects.goal=String(goal).slice(0,300);return {ok:true};}
export function shareProject(s,text){const p=project(s);if(!p.goal||p.lessons<p.required)return {error:'계획과 연결한 실제 수업 '+p.required+'차시를 먼저 기록해 주세요.'};if(data(s).projects.shared)return {error:'운영 결과를 이미 공유했습니다.'};if(!String(text).trim()||!free(s,20))return {error:'학생 반응과 다음 개선점을 적고 20분을 확보해 주세요.'};M.advance(s,20);data(s).projects.shared=true;data(s).projects.report=String(text).slice(0,1000);M.addMessage(s,'grade','나',p.topic+' 선도사업 우리 반 결과: '+text,{senderId:'teacher',plannerScanned:true});return {ok:true};}
export function audit(s){const d=data(s),school=Career.data(s).schools.find(x=>x.id===Career.data(s).schoolId),due=school.lastAudit+school.auditCycle;if(d.currentAudit?.schoolId!==school.id)d.currentAudit=null;if(s.academic.year>=due&&!d.currentAudit)d.currentAudit={schoolId:school.id,year:s.academic.year,stage:0,notes:[],done:false};return {school,due,current:d.currentAudit};}
export function auditStep(s,text){const a=audit(s);if(!a.current||a.current.done)return {error:'현재 진행 중인 감사가 없습니다.'};if(String(text).trim().length<8||!free(s,20))return {error:'담임 소관의 확인 내용과 근거를 적고 20분을 확보해 주세요.'};if(a.current.stage===0&&!s.classCurriculum?.active)return {error:'학급교육과정과 실제 기록을 먼저 확인해 주세요. 없는 기록을 소급 생성하지 않습니다.'};M.advance(s,20);a.current.notes.push({stage:a.current.stage,text:String(text).slice(0,1000),date:M.stamp(s),records:{lessons:s.lessonResults.length,purchases:s.purchases.length,observations:s.students.reduce((n,st)=>n+st.records.length,0)}});a.current.stage++;if(a.current.stage===4){a.current.done=true;a.school.lastAudit=s.academic.year;data(s).history.push(structuredClone(a.current));}return {ok:true};}
export function committee(s,kind,vote,text){const c=Career.data(s),allowed=kind==='부장회의'?c.post==='부장':data(s).committeeMember===true;if(!String(text).trim())return {error:'공유할 의견이나 확인 내용을 적어 주세요.'};if(vote&&!allowed)return {error:kind+'의 참여 자격이 없어 표결할 수 없습니다. 자료 공유와 학급 의견 전달은 가능합니다.'};if(!free(s,20))return {error:'수업·약속과 겹치지 않는 20분이 필요합니다.'};M.advance(s,20);data(s).committees.push({kind,vote:vote||null,role:allowed?'참여 대상':'자료·의견 전달',text:String(text).slice(0,1000),date:M.stamp(s),day:s.day});return {ok:true};}
export function organize(s,kind){const d=data(s),key=s.academic.year+'-'+A.term(s)+'-'+kind;if(d.organizations.some(x=>x.id===key))return {error:'이번 학기 안내와 희망 확인을 진행했습니다.'};const volunteers=s.students.filter((x,i)=>(i+s.config.seed+A.term(s))%3===0).map(x=>x.parentId);d.organizations.push({id:key,kind,volunteers,date:M.stamp(s),alternative:'희망자와 학교 지원 인력으로 조정',studentPenalty:0});M.addMessage(s,'parent','나',kind+' 참여 희망과 가능한 시간을 확인합니다. 참여는 자율이며 미참여 가정의 학생에게 불이익이 없습니다.',{senderId:'teacher',plannerScanned:true});return {ok:true};}
export function valid(s){const d=s.staffWork;if(d==null)return true;return d.schema===1&&Array.isArray(d.training)&&d.training.every(r=>COURSES.some(c=>c.id===r.courseId)&&r.hours===1&&typeof r.practice==='boolean')&&Array.isArray(d.business)&&d.business.every(t=>['requested','approved','on-site','completed','cancelled'].includes(t.status)&&t.end<=1000&&t.start>=900&&t.day>=0&&t.day<M.demoDays(s))&&Array.isArray(d.social)&&Array.isArray(d.committees)&&Array.isArray(d.organizations)&&Array.isArray(d.history)&&(!d.away||d.business.some(t=>t.id===d.away&&t.status==='on-site'));}
